```tsx
import { useId } from "react";
import "./ChecklistItem.css";

export interface ChecklistItemProps {
  title: string;
  detail: string;
  minutes: number;
  done: boolean;
  onToggle: () => void;
}

export function ChecklistItem({ title, detail, minutes, done, onToggle }: ChecklistItemProps) {
  const titleId = useId();
  const detailId = useId();

  return (
    <div className={done ? "checklist-item is-done" : "checklist-item"}>
      <button
        type="button"
        className="checklist-item__check"
        aria-pressed={done}
        aria-labelledby={titleId}
        aria-describedby={detailId}
        onClick={onToggle}
      >
        {done && (
          <svg className="checklist-item__tick" viewBox="0 0 16 16" aria-hidden="true" focusable="false">
            <path
              d="M3.5 8.5l3 3 6-7"
              fill="none"
              stroke="currentColor"
              strokeWidth={2.5}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        )}
      </button>
      <div className="checklist-item__text">
        <span id={titleId} className="checklist-item__title">
          {title}
        </span>
        <span id={detailId} className="checklist-item__detail">
          {detail}
        </span>
      </div>
      <span className="checklist-item__minutes">{minutes} min</span>
    </div>
  );
}
```

```css
.checklist-item {
  display: flex;
  align-items: center;
  gap: clamp(0.75rem, 1.5vw, 1.25rem);
  padding: clamp(0.75rem, 1.4vw, 1.1rem) 0;
  border-bottom: 1px solid var(--hair);
  color: var(--ink);
}

.checklist-item__check {
  flex: none;
  display: grid;
  place-items: center;
  width: clamp(1.75rem, 2.6vw, 2.25rem);
  aspect-ratio: 1;
  padding: 0;
  border-radius: 50%;
  border: 2px solid var(--muted);
  background: transparent;
  color: var(--ink);
  font: inherit;
  cursor: pointer;
  transition: background-color 160ms ease, border-color 160ms ease;
}

.checklist-item__check:hover {
  border-color: var(--ink);
}

.checklist-item__tick {
  width: 60%;
  height: 60%;
}

.checklist-item__text {
  flex: 1;
  min-width: 0;
}

.checklist-item__title {
  display: block;
  font-size: clamp(1rem, 1.2vw + 0.5rem, 1.25rem);
  color: var(--ink);
  transition: color 160ms ease;
}

.checklist-item__detail {
  display: block;
  margin-top: 0.2rem;
  font-size: clamp(0.8rem, 0.9vw + 0.4rem, 0.95rem);
  color: var(--muted);
}

.checklist-item__minutes {
  flex: none;
  font-size: clamp(0.85rem, 0.9vw + 0.4rem, 1rem);
  color: var(--muted);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.checklist-item.is-done .checklist-item__check {
  background: var(--myelin);
  border-color: var(--myelin);
  color: var(--slide);
}

.checklist-item.is-done .checklist-item__title {
  color: var(--muted);
  text-decoration: line-through;
}

:root[data-motion="reduce"] .checklist-item__check,
:root[data-motion="reduce"] .checklist-item__title {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .checklist-item__check,
  .checklist-item__title {
    transition: none;
  }
}
